{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "In a rat tissue distribution study, epimedin B, a highly polar polyglycoside with multiple sugar residues, was the least concentrated compound in brain and could hardly pass the blood-brain barrier; this directly supports that glycoside/glucuronide-type conjugates with high polarity and many H-bond donors do not achieve meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Posiphen showed a brain-to-plasma ratio of 5.04 in mice and was classified as high permeability, but this reflects a lipophilic phenserine-like scaffold lacking the glucuronide and zwitterionic character of the query, so this positive result is not mechanistically transferable to the query's CNS access.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a morphine-3-glucuronide-like zwitterionic glucuronide with very high polarity, multiple H-bond donors/acceptors, and essentially no neutral fraction at physiological pH. Direct evidence from a polar polyglycoside (epimedin B) shows negligible brain distribution, while the lipophilic CNS-penetrant analogues lack the glucuronide/zwitterionic features that dominate the query's disposition. Therefore, meaningful CNS access after systemic administration is unlikely.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF pharmacokinetic data for the query molecule itself are included in the evidence set.",
    "Transporter-mediated disposition of the glucuronide (e.g., OATP/OAT, P-gp, BCRP) is not experimentally characterized in the provided records.",
    "The closest glycoside analogue (epimedin B) is larger and more heavily glycosylated than the query, so quantitative transfer is approximate."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

